starterCode:
function createLRU(maxSize) {
  // TODO: return get, set
}

solution:
function createLRU(maxSize) {
  const cache = new Map();
  return {
    get: (key) => {
      if (!cache.has(key)) return undefined;
      const val = cache.get(key);
      cache.delete(key);
      cache.set(key, val);
      return val;
    },
    set: (key, val) => {
      if (cache.has(key)) cache.delete(key);
      if (cache.size >= maxSize) cache.delete(cache.keys().next().value);
      cache.set(key, val);
    }
  };
}

