starterCode:
function createConnectionPool(maxSize) {
  // TODO: return acquire, release
}

solution:
function createConnectionPool(maxSize) {
  const pool = [];
  const active = [];
  for (let i = 0; i < maxSize; i++) pool.push({id: i});
  return {
    acquire: () => {
      const conn = pool.pop();
      if (conn) active.push(conn);
      return conn;
    },
    release: (conn) => {
      const idx = active.findIndex(c => c.id === conn.id);
      if (idx >= 0) {
        active.splice(idx, 1);
        pool.push(conn);
      }
    },
    size: () => pool.length
  };
}

